using System.ClientModel;
using Azure.AI.OpenAI;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.Configuration;

namespace MyApp.Evals;

[TestClass]
public sealed class EvalTests
{
    private static ReportingConfiguration? s_reportingConfig;

    private static IChatClient CreateChatClient()
    {
        var config = new ConfigurationBuilder()
            .AddEnvironmentVariables()
            .Build();

        var endpoint = config["AZURE_OPENAI_ENDPOINT"]
            ?? throw new InvalidOperationException("Set the AZURE_OPENAI_ENDPOINT environment variable.");
        var apiKey = config["AZURE_OPENAI_API_KEY"]
            ?? throw new InvalidOperationException("Set the AZURE_OPENAI_API_KEY environment variable.");
        var deployment = config["AZURE_OPENAI_DEPLOYMENT"] ?? "gpt-4o-mini";

        return new AzureOpenAIClient(new Uri(endpoint), new ApiKeyCredential(apiKey))
            .GetChatClient(deployment)
            .AsIChatClient();
    }

    private static ReportingConfiguration GetReportingConfiguration()
    {
        s_reportingConfig ??= DiskBasedReportingConfiguration.Create(
            storageRootPath: Path.Combine(Directory.GetCurrentDirectory(), "eval-results"),
            evaluators:
            [
                new CoherenceEvaluator(),
                new RelevanceEvaluator(),
                new FluencyEvaluator(),
                new GroundednessEvaluator(),
            ],
            chatConfiguration: new ChatConfiguration(CreateChatClient()));

        return s_reportingConfig;
    }

    [TestMethod]
    public async Task AnswerRelevance_SimpleQuestion()
    {
        await using var scenario = await GetReportingConfiguration()
            .CreateScenarioRunAsync(scenarioName: nameof(AnswerRelevance_SimpleQuestion));

        var chatClient = CreateChatClient();
        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What is the capital of France?")
        };

        var response = await chatClient.GetResponseAsync(messages);
        messages.Add(response.Message);

        await scenario.EvaluateAsync(messages);

        EvaluationAssertions.AssertAllMetricsAboveThreshold(scenario, threshold: 3.0);
    }

    [TestMethod]
    public async Task AnswerRelevance_FollowUp()
    {
        await using var scenario = await GetReportingConfiguration()
            .CreateScenarioRunAsync(scenarioName: nameof(AnswerRelevance_FollowUp));

        var chatClient = CreateChatClient();
        var messages = new List<ChatMessage>
        {
            new(ChatRole.System, "You are a helpful assistant that answers questions concisely."),
            new(ChatRole.User, "Summarize the benefits of unit testing in software development.")
        };

        var response = await chatClient.GetResponseAsync(messages);
        messages.Add(response.Message);

        await scenario.EvaluateAsync(messages);

        EvaluationAssertions.AssertAllMetricsAboveThreshold(scenario, threshold: 3.0);
    }

    [TestMethod]
    public async Task Groundedness_WithContext()
    {
        await using var scenario = await GetReportingConfiguration()
            .CreateScenarioRunAsync(scenarioName: nameof(Groundedness_WithContext));

        var chatClient = CreateChatClient();
        var context = """
            The Eiffel Tower is located in Paris, France. It was constructed in 1889
            and stands approximately 330 meters tall. It was designed by Gustave Eiffel.
            """;

        var messages = new List<ChatMessage>
        {
            new(ChatRole.System, $"Answer questions using only the following context:\n{context}"),
            new(ChatRole.User, "Who designed the Eiffel Tower and when was it built?")
        };

        var response = await chatClient.GetResponseAsync(messages);
        messages.Add(response.Message);

        await scenario.EvaluateAsync(messages);

        EvaluationAssertions.AssertAllMetricsAboveThreshold(scenario, threshold: 3.0);
    }
}

internal static class EvaluationAssertions
{
    public static void AssertAllMetricsAboveThreshold(ScenarioRun scenario, double threshold)
    {
        foreach (var result in scenario.AllEvaluationResults)
        {
            foreach (var metric in result.Metrics.Values)
            {
                if (metric is NumericMetric numericMetric)
                {
                    Assert.IsTrue(
                        numericMetric.Value >= threshold,
                        $"Metric '{metric.Name}' scored {numericMetric.Value}, below threshold {threshold}.");
                }
            }
        }
    }
}

